assert subprocess.check_output(['git','show',':docs/vehicle_fleet/Dead_Street_Vehicle_Fleet_Guide.pdf'],cwd=ROOT)==(ROOT/'docs/vehicle_fleet/Dead_Street_Vehicle_Fleet_Guide.pdf').read_bytes()
print('REVIEWED_SCOPE',len(staged),git('diff','--cached','--shortstat'),flush=True)
